// ============================================================================
// TapMyCar - Patch 35b-scan-fix: Embed jsQR locally + fix viewfinder
//
// Issues from user testing:
//   1. "Could not load QR scanner. Check your internet connection."
//      The cdnjs URL was either blocked by the service worker, CSP, or
//      simply unreachable. Solution: ship jsQR from same-origin.
//   2. Viewfinder corners look broken on desktop. Rewriting layout with
//      absolute positioning anchored to a fixed-size centered box.
//
// jsQR (256 KB) is embedded into THIS patch script as a base64-encoded
// gzip blob. On run, the script decompresses it and writes
// public/vendor/jsQR.js. No network download required.
// ============================================================================

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const ROOT = __dirname;
const PUBLIC = path.join(ROOT, 'public');
const VENDOR = path.join(PUBLIC, 'vendor');

const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 16);
const BACKUP_DIR = path.join(ROOT, 'backup-patch35bscanfix-' + ts);

const log = (s) => console.log(s);
const ok = (s) => console.log('  \u2713 ' + s);
const skip = (s) => console.log('  \u00b7 ' + s + ' (already applied, skipped)');
const errExit = (s) => { console.error('  \u2717 ' + s); process.exit(1); };

function readFile(p) { return fs.readFileSync(p, 'utf8'); }
function backup(file) {
  if (!fs.existsSync(file)) return;
  const rel = path.relative(ROOT, file);
  const dest = path.join(BACKUP_DIR, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(file, dest);
}
function writeFile(p, content) {
  if (typeof content === 'string' && content.charCodeAt(0) === 0xFEFF) content = content.slice(1);
  fs.writeFileSync(p, content);
}
function safeReplace(content, oldStr, newStr) {
  const oldCRLF = oldStr.replace(/\n/g, '\r\n');
  if (content.includes(oldStr)) return content.replace(oldStr, () => newStr);
  if (content.includes(oldCRLF)) {
    const newCRLF = newStr.replace(/\n/g, '\r\n');
    return content.replace(oldCRLF, () => newCRLF);
  }
  return null;
}

log('');
log('TapMyCar Patch 35b-scan-fix \u2014 embed jsQR + fix viewfinder');
log('Backup: ' + path.relative(ROOT, BACKUP_DIR));
log('');
fs.mkdirSync(BACKUP_DIR, { recursive: true });

const MARKER = 'TMC_PATCH35BSCANFIX_BUNDLED';

// jsQR 1.4.0 from npm, gzip-compressed and base64-encoded.
const JSQR_GZ_B64 = '';

log('35b-scan-fix.1  public/vendor/jsQR.js: write embedded library');
{
  const vendorFile = path.join(VENDOR, 'jsQR.js');
  if (fs.existsSync(vendorFile) && fs.statSync(vendorFile).size > 100000) {
    skip('jsQR.js (already present)');
  } else {
    fs.mkdirSync(VENDOR, { recursive: true });
    try {
      const compressed = Buffer.from(JSQR_GZ_B64, 'base64');
      const js = zlib.gunzipSync(compressed);
      writeFile(vendorFile, js);
      ok('jsQR.js written (' + js.length + ' bytes uncompressed)');
    } catch (e) {
      errExit('Failed to decompress embedded jsQR: ' + e.message);
    }
  }
}

log('');
log('35b-scan-fix.2  public/admin.html: bundled loader + viewfinder fix');
{
  const file = path.join(PUBLIC, 'admin.html');
  const content = readFile(file);
  if (content.includes(MARKER)) {
    skip('admin.html (already patched)');
  } else {
    backup(file);
    let updated = content;

    const oldLoader = `async function p35bsLoadJsQr() {\n  if (p35bsQrLib || (typeof jsQR === 'function')) {\n    return Promise.resolve();\n  }\n  return new Promise(function(resolve, reject) {\n    var s = document.createElement('script');\n    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jsQR/1.4.0/jsQR.min.js';\n    s.onload = function() { resolve(); };\n    s.onerror = function() { reject(new Error('Failed to load QR library')); };\n    document.head.appendChild(s);\n  });\n}`;

    const newLoader = `async function p35bsLoadJsQr() {\n  /* ${MARKER}: load from same-origin /vendor/jsQR.js */\n  if (typeof window.jsQR === 'function') return Promise.resolve();\n  return new Promise(function(resolve, reject) {\n    var s = document.createElement('script');\n    s.src = '/vendor/jsQR.js';\n    s.async = true;\n    s.onload = function() {\n      if (typeof window.jsQR === 'function') resolve();\n      else reject(new Error('jsQR loaded but global not exposed'));\n    };\n    s.onerror = function() { reject(new Error('Failed to load /vendor/jsQR.js')); };\n    document.head.appendChild(s);\n  });\n}`;

    let r = safeReplace(updated, oldLoader, newLoader);
    if (!r) errExit('admin.html: p35bsLoadJsQr anchor not found');
    updated = r;
    ok('jsQR loader switched to /vendor/jsQR.js');

    // Viewfinder fix
    const oldViewfinder = `  <!-- Viewfinder overlay -->\n  <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:2">\n    <div style="position:relative;width:240px;height:240px">\n      <div style="position:absolute;top:0;left:0;width:34px;height:34px;border-top:4px solid #FF6B00;border-left:4px solid #FF6B00;border-radius:6px 0 0 0"></div>\n      <div style="position:absolute;top:0;right:0;width:34px;height:34px;border-top:4px solid #FF6B00;border-right:4px solid #FF6B00;border-radius:0 6px 0 0"></div>\n      <div style="position:absolute;bottom:0;left:0;width:34px;height:34px;border-bottom:4px solid #FF6B00;border-left:4px solid #FF6B00;border-radius:0 0 0 6px"></div>\n      <div style="position:absolute;bottom:0;right:0;width:34px;height:34px;border-bottom:4px solid #FF6B00;border-right:4px solid #FF6B00;border-radius:0 0 6px 0"></div>\n      <!-- scanning line -->\n      <div id="p35bs-scanline" style="position:absolute;top:0;left:8px;right:8px;height:2px;background:linear-gradient(90deg,transparent,#FF6B00,transparent);box-shadow:0 0 12px #FF6B00;animation:p35bs-scan 2s ease-in-out infinite"></div>\n    </div>\n  </div>`;

    const newViewfinder = `  <!-- ${MARKER}: Viewfinder \u2014 fixed clean layout -->\n  <div style="position:absolute;inset:0;z-index:2;pointer-events:none">\n    <div style="position:absolute;top:50%;left:50%;width:260px;height:260px;margin:-130px 0 0 -130px;box-sizing:border-box">\n      <span style="position:absolute;top:0;left:0;display:block;width:36px;height:36px;border-top:4px solid #FF6B00;border-left:4px solid #FF6B00;border-radius:6px 0 0 0;box-sizing:border-box"></span>\n      <span style="position:absolute;top:0;right:0;display:block;width:36px;height:36px;border-top:4px solid #FF6B00;border-right:4px solid #FF6B00;border-radius:0 6px 0 0;box-sizing:border-box"></span>\n      <span style="position:absolute;bottom:0;left:0;display:block;width:36px;height:36px;border-bottom:4px solid #FF6B00;border-left:4px solid #FF6B00;border-radius:0 0 0 6px;box-sizing:border-box"></span>\n      <span style="position:absolute;bottom:0;right:0;display:block;width:36px;height:36px;border-bottom:4px solid #FF6B00;border-right:4px solid #FF6B00;border-radius:0 0 6px 0;box-sizing:border-box"></span>\n      <span id="p35bs-scanline" style="position:absolute;top:0;left:8px;right:8px;height:2px;background:linear-gradient(90deg,transparent,#FF6B00,transparent);box-shadow:0 0 12px #FF6B00;animation:p35bs-scan 2s ease-in-out infinite;display:block"></span>\n    </div>\n  </div>`;

    r = safeReplace(updated, oldViewfinder, newViewfinder);
    if (!r) errExit('admin.html: viewfinder anchor not found');
    updated = r;
    ok('Viewfinder repositioned with clean layout');

    const oldKeyframes = `@keyframes p35bs-scan {\n  0%, 100% { transform: translateY(0); }\n  50% { transform: translateY(232px); }\n}`;
    const newKeyframes = `@keyframes p35bs-scan {\n  0%, 100% { transform: translateY(0); }\n  50% { transform: translateY(252px); }\n}`;
    r = safeReplace(updated, oldKeyframes, newKeyframes);
    if (r) { updated = r; ok('Scan line keyframes updated'); }

    writeFile(file, updated);
  }
}

log('');
log('===============================================================');
log('Patch 35b-scan-fix complete.');
log('Backup folder: ' + path.relative(ROOT, BACKUP_DIR));
log('');
log('Deploy:');
log('  git add -A');
log('  git commit -m "Patch 35b-scan-fix: embed jsQR + fix viewfinder"');
log('  git push');
log('  Wait ~60 sec.');
log('');
log('Hard refresh on phone (incognito or force-close browser).');
log('Then admin \u2192 Promos \u2192 Scan QR. Camera + viewfinder should work.');
log('===============================================================');
